-- Load dynamic iris palette with Tokyo Dark fallback, dark clamping & vibrancy boost
local default_iris = {
	bg = "08090d",
	fg = "e5e9f0",
	surface = "11131c",
	dim = "7e889b",
	accent = "7199ee",
	red = "ee6d85",
	green = "9ece6a",
	yellow = "d7a65f",
}

local function transform_hypr_hex(hex, fallback, mode, p1, p2, p3)
	local val = (type(hex) == "string") and hex:gsub("^#", "") or ""
	if not val:match("^%x%x%x%x%x%x$") then
		val = fallback
	end
	local r = tonumber(val:sub(1, 2), 16)
	local g = tonumber(val:sub(3, 4), 16)
	local b = tonumber(val:sub(5, 6), 16)
	local luma = 0.2126 * r + 0.7152 * g + 0.0722 * b

	if mode == "dark" then
		r = r * (1 - p2) + luma * p2
		g = g * (1 - p2) + luma * p2
		b = b * (1 - p2) + luma * p2
		if luma > p1 and luma > 0 then
			local s = p1 / luma
			r, g, b = r * s, g * s, b * s
		end
	elseif mode == "vibrant" then
		local avg = (r + g + b) / 3
		r = math.max(0, math.min(255, avg + (r - avg) * p1))
		g = math.max(0, math.min(255, avg + (g - avg) * p1))
		b = math.max(0, math.min(255, avg + (b - avg) * p1))
		luma = 0.2126 * r + 0.7152 * g + 0.0722 * b
		if luma < p2 then
			if luma < 5 then
				r, g, b, luma = 40, 45, 60, 46
			end
			local s = p2 / luma
			r = math.min(255, r * s)
			g = math.min(255, g * s)
			b = math.min(255, b * s)
		elseif p3 and luma > p3 and luma > 0 then
			local s = p3 / luma
			r, g, b = r * s, g * s, b * s
		end
	end
	return string.format("%02x%02x%02x", math.floor(r), math.floor(g), math.floor(b))
end

local iris = {}
local iris_cache = os.getenv("HOME") .. "/.cache/iris/colors-hypr.lua"
local ok, loaded = pcall(dofile, iris_cache)
local raw = (ok and type(loaded) == "table") and loaded or {}

iris.bg = transform_hypr_hex(raw.bg, default_iris.bg, "dark", 8, 0.45)
iris.surface = transform_hypr_hex(raw.surface, default_iris.surface, "dark", 18, 0.35)
iris.fg = transform_hypr_hex(raw.fg, default_iris.fg, "vibrant", 1.20, 215, 245)
iris.dim = transform_hypr_hex(raw.dim, default_iris.dim, "vibrant", 1.15, 105, 135)
iris.accent = transform_hypr_hex(raw.accent, default_iris.accent, "vibrant", 1.75, 155, 225)
iris.red = transform_hypr_hex(raw.red, default_iris.red, "vibrant", 1.75, 145, 220)
iris.green = transform_hypr_hex(raw.green, default_iris.green, "vibrant", 1.75, 160, 225)
iris.yellow = transform_hypr_hex(raw.yellow, default_iris.yellow, "vibrant", 1.70, 170, 230)

